# coding:utf-8
import json,sys
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parents[2]/'scripts'))
from common import ROOT
initial={r['question_id']:r for r in json.loads((ROOT/'config/authored_batches/S7_042_independent_answers.json').read_text())['records']}
selected={r['question_id']:r for r in json.loads((ROOT/'extracted/logs/S7_042_electrical_borehole_selection.json').read_text())['records']}
out=[];T='適切';F='不適切';C='条件付きで適切'
def add(q,stem,cid,labels,knowledge,solution,options,learning,cites,ambiguity='',discipline='geo_exploration'):
 r=selected[q];i=initial[q];year='R01_retest' if '-RET-' in q else q.split('-')[0];im=f'extracted/pages/{year}/17_applied_science/page_{int(r["source_page"]):03}.png'
 assert len(options)==5
 out.append(dict(question_id=q,source_sha256=r['source_sha256'],stem=stem,summary=stem,conditions={'原典照合':'29問21原典画像で否定、全五候補、数式・上付き単位・観測対象を照合。','前提':knowledge},choices={str(n):dict(value=v,verdict=j,reason=why) for n,(v,j,why) in enumerate(options,1)},figures='図なし。H28問23のWenner式とMT式及びH26/R03の単位指数を画像確認。',ambiguity=ambiguity,evidence=[im],core_concept=stem,required_knowledge=knowledge,solution=solution,answer_reason=solution,independent_answer=i['answer_initial'],independent_solution_note='公式前の初回29問を別保存。'+i['reason'],learning_points=learning,theory_references=labels,discipline_id=discipline,concept_id=cid,cross_concepts=[],classification_reason=('岩石・岩盤の強度評価指標を比較するため応用地質へ修正する。' if discipline=='geo_engineering' else '観測量、電気特性、測定配置及び地下推定の限界を問う物理探査へ配置する。')+learning,calculation='false',figure='false',law='false',evaluation=dict(knowledge_novelty='2',reasoning_steps='2',calculation_load='0',figure_reading='0',difficulty='3' if ambiguity else '2',difficulty_reason='手法名だけでなく観測量・単位・送受信配置・適用条件から判別する。'+('全称や深度推定・代理指標の限界も吟味する。' if ambiguity else '定義と五候補の対応で判定する。')),citations=cites,foundationality='high',transferability='high'))
add('H23-REG-APPLIED-30','比抵抗法の電極配置・計算法とIP分極測定を比較する。','exploration_dc_arrays',['theory:exploration:dcarrays','theory:exploration:ipsp'],'直流比抵抗の電極配列・順計算と、時間又は周波数に依存する分極応答を分ける。','2のIP法が、静的な比抵抗を求める三配列とlinear filter計算に対して相対的に別の観測を加える。IPも比抵抗と電極を共有するため、無関係とまでは言えない。4は層状構造の比抵抗変換から見掛比抵抗を計算する線形フィルタである。',[
 ('ウェンナー法',T,'等間隔の四電極配置で電流と電位差から見掛比抵抗を求める。'),('IP法',C,'電流印加で生じる分極の減衰又は位相を測る。静的比抵抗法とは目的量が異なるが、同じ配置で比抵抗も測るので関係のなさは相対的である。'),('シュランベルジャー法',T,'電流電極と短い電位電極対を使う比抵抗垂直探査の代表的配置である。'),('リニアフィルタ法',T,'層状比抵抗モデルの順応答計算に用いられる。一般の信号ノイズ処理だけと解釈しない。'),('ダイポール・ダイポール法',T,'電流双極子と電位双極子を離した比抵抗配置で、二次元調査等に用いる。')],
 '測定配置、順計算法、追加の分極観測を同じ種類の名称と思わない。',['epa_resistivity','epa_ip','usgs_linear_filter1981'],ambiguity='最も関係ないは相対比較である。IPは比抵抗測定と密接に関連するため完全な非関連とは説明しない。')
add('H24-REG-APPLIED-20','電極による比抵抗測定とコイルによる電磁誘導を区別する。','exploration_dc_arrays',['theory:exploration:dcarrays','theory:exploration:fdtd'],'電気的接触を持つ電極測定と送受信ループの誘導測定を区別する。','5のループ・ループ法が電磁誘導による手法である。残りは電極の接触、配列、見掛比抵抗という電流注入型比抵抗測定に直接関係する。',[
 ('接地抵抗',T,'地盤へ電流を流す電極の接触抵抗が送信と測定条件へ影響する。'),('ウェンナー法',T,'等間隔四電極の比抵抗配置である。'),('見掛け比抵抗',T,'測ったV/Iへ配置の幾何係数を掛けた等価半空間の抵抗率である。'),('電極',T,'電流印加と電位差測定に用いる。'),('ループ・ループ法',F,'送受信コイルから地盤の誘導電流応答を測る手法で、電極を使う直流比抵抗測定の用語ではない。比抵抗を推定する目的自体は共通する。')],
 '推定する物性が同じでも励起・受信の仕組みが異なる。',['epa_resistivity','epa_fdem'])
add('H25-REG-APPLIED-34','四電極法で接触抵抗の電圧降下を分離する理由を選ぶ。','exploration_four_electrode',['theory:exploration:fourpoint'],'電流注入電極と高入力抵抗の電位測定電極を分ける。電位電極電流は十分小さい。','3である。二端子では地盤に加えて電流電極の接触抵抗の電圧降下も測る。別の電位電極へ高入力抵抗の電圧計を接続すれば、その電極を流れる電流が小さく、接触抵抗による誤差を軽減する。送信側の接地抵抗は依然として電流確保に影響する。',[
 ('電磁カップリングを小さくする',F,'電磁誘導の結合はケーブル配置・周波数等にも依存し、四電極化の主要な理由ではない。'),('測定電圧を大きくする',F,'Vは電極幾何と地盤応答で決まり、電極を分けることだけで増大しない。'),('接地抵抗の影響を軽減する',T,'電流端子の接触電圧降下を電位差観測から分け、電位端子の小電流によりその接触降下も抑える。'),('地形の影響を無視する',F,'地形は電流分布を変えるため、別電位電極でも順モデルの地形補正が必要である。'),('探査深度を大きくする',F,'深度感度は配列と間隔等で決まり、電極端子を分ける理由そのものではない。')],
 '送信電流を確保する問題と、電位測定の接触誤差を減らす問題を分ける。',['epa_resistivity'])
add('H24-REG-APPLIED-22','孔内弾性波速度測定とnormal電気検層を区別する。','exploration_borehole_signals',['theory:exploration:borehole'],'振源・受振器の位置と直接観測する物性を対応させる。','2のノルマル法は電極配置による比抵抗検層である。downhole、uphole、VSP、suspensionは弾性波走時又は波形を測り速度構造に関連する。',[
 ('ダウンホール法',T,'地表起振、孔内受振で到達走時から速度を求める。'),('ノルマル法',F,'電極の間隔を定めて孔周辺の見掛比抵抗を測り、弾性波速度を直接測る方法ではない。'),('アップホール法',T,'孔内起振、地表受振で弾性波走時を測る。'),('VSP法',T,'孔内受振等の波形と深度を用い、速度と反射構造を対応させる。'),('サスペンション法',T,'孔内振源と複数受振器の到達時間差から区間速度を求める。')],
 '名称だけでなくセンサと観測量を思い出す。',['epa_borehole_resistivity','geebec_ps','oyo_suspension'])
vsp=('VSPで孔内に振源又は受振器を設置し反射波を測る',C,'通常の地表振源・孔内受振と逆VSPなどの構成を区別する。孔内深度と反射記録を結び地表反射探査の解釈を助ける。')
down=('ダウンホールで地表起振・孔内受振の初動走時を測る',T,'孔壁に結合した受振器の位置と走時から区間速度を推定する。経路と屈折の補正が必要である。')
susp=('サスペンションで孔内振源と複数受振器を用いる',T,'孔内ゾンデの起振と受振点間の走時差により、孔軸に沿う地盤の区間速度を求める。水中のS波伝播を直接測るという意味ではない。')
elect=('電極検層は孔内と地表の電極で比抵抗を測り裸孔を基本とする',C,'通常のnormal電極検層では導電孔内流体を介して地層へ電流を流す。金属ケーシングの影響を避ける。誘導検層等の別方式へこの条件をそのまま一般化しない。')
gamma=('ガンマ線散乱で孔壁周辺の密度を測り孔隙率を推定する',T,'主にCompton散乱に関わる電子密度を校正してかさ密度を求める。粒子と流体の密度が既知なら孔隙率を推定できる。')
for q,stem,sol,rows,amb in [
 ('H23-REG-APPLIED-31','孔内速度・電気・密度検層の水位条件を比較する。','2が誤りである。孔壁に密着させるダウンホール受振器は孔内水位より上でも測定できる。水による振動結合を使う他方式や、導電流体を要する電極検層と区別する。',[vsp,('ダウンホールは孔内水位以深だけに適用可能',F,'孔壁へ固定・密着した受振器なら水位のない部分でも測定できる。孔内水位以深だけという限定が誤りである。'),susp,elect,gamma],'VSPの振源又は受振器は通常型と逆配置を含む。裸孔条件は電極検層の基本条件であり全検層へ拡張しない。'),
 ('R01-REG-APPLIED-33','密度検層の放射線と粒子密度・かさ密度を区別する。','3が不適切である。密度検層はガンマ線の主にCompton散乱による電子密度から孔周辺のかさ密度を求める。ベータ線でも粒子密度の直接測定でもない。',[vsp,('ダウンホールは孔内水の有無が問題とならない',C,'孔壁結合が確保できれば水位より上も測定できる。ただし孔壁崩壊や受振器の結合条件は測定品質へ影響する。'),('ベータ線の散乱で地層の粒子密度を測る',F,'線種はガンマ線、主観測は電子密度から校正するかさ密度である。二つの観測対象を取り違える。'),elect,susp],'水の有無だけでdownhole可否は決まらないが、全孔内条件の非依存性を保証しない。VSPと裸孔は方式を特定する。'),
 ('R05-REG-APPLIED-34','電極検層の孔内流体と各検層の信号を対応させる。','4が不適切である。通常の電極型電気検層は孔内の水又は導電泥水を通じて地層へ電流を流すため、その有無と電気特性が問題になる。ダウンホールの孔壁結合とは別である。',[down,susp,gamma,('電極検層で孔内水の有無は問題とならない',F,'電極から地層へ電流を流す導電接触が必要で、孔内流体は電流経路と測定値に影響する。電磁誘導検層との混同である。'),vsp],'VSPに通常型と逆配置があり、電極検層と誘導検層の条件を区別する。ガンマ密度の孔壁・孔内流体補正も保持。'),
 ('R07-REG-APPLIED-34','ガンマ密度検層のCompton散乱と誤った線種を比較する。','4が不適切である。通常の密度検層はガンマ線のCompton散乱を利用して校正したかさ密度を求める。ベータ線のRayleigh散乱とする原典記述を正しい文章へ改変しない。',[('電極検層の測定区間は孔内水位以深',C,'通常の裸孔電極検層では導電水・泥水を介する区間を測る。電極接触を持たない誘導検層などには一般化しない。'),down,vsp,('ベータ線のレイリー散乱で密度分布を測る',F,'ガンマ線のCompton散乱が主要な原理である。電子密度と岩石かさ密度の校正を使う。'),susp],'水位条件は通常の電極検層についてである。VSPの逆配置や孔内流体・孔壁接触による密度補正を別に扱う。')]:
 add(q,stem,'exploration_borehole_signals',['theory:exploration:borehole','theory:exploration:gammadensity'],'速度検層は弾性波、電極検層は比抵抗、ガンマ密度検層は校正かさ密度である。',sol,rows,'流体、孔壁結合、線種、センサ位置を観測量ごとに整理する。',['epa_borehole_resistivity','epa_gamma_density','geebec_ps','oyo_suspension'],ambiguity=amb)
add('H26-REG-APPLIED-19','各物理探査の観測量とP波速度の含水依存を比較する。','exploration_multimethod',['theory:exploration:borehole','theory:exploration:waveproperties'],'P波速度は弾性率と密度で決まり、飽和や孔隙流体は両者と接触状態を変え得る。','5が不適切である。P波速度は飽和・含水状態で変わり得る。Vp=√((K+4µ/3)/ρ)の剛性と密度が含水で変化するため、一般に不変とすることはできない。単純な含水比だけから全地盤の単調変化は予測しない。',[
 ('重力が密度・深度・形状を反映する',T,'密度差の体積積分が重力へ寄与し、同じ密度でも深度と形状で観測異常が変わる。'),('通常の屈折法は地表でP波初動を測る',C,'地表から広い対象を調査しP初動を使う構成が一般的である。S波方式や隠れ層の限界もある。'),('ダウンホールは孔内速度測定方式',T,'地表起振・孔内受振の走時を使う。'),('ガンマ線で深度方向の密度検層',T,'線源と受信器を降下させ孔壁周囲の校正かさ密度を測る。'),('P波速度は一般に含水比によらず不変',F,'孔隙流体による有効弾性率と密度・接触の変化があるため、含水依存を一般に除外できない。')],
 '一つの観測物性を水分と切り離さず、波速と密度の感度を考える。',['epa_gamma_density','geebec_ps','epa_seismic_refraction'],ambiguity='含水比・飽和度・間隙流体を区別し、P波速度の全材料での単調変化を主張しない。P波初動の利点は通常の方式に限定する。')
add('H27-REG-APPLIED-18','粘土・不飽和・割れ目・海水が比抵抗へ与える傾向を比較する。','exploration_archie',['theory:exploration:archie','theory:exploration:borehole'],'孔隙水のイオン伝導と粘土表面伝導、含水した割れ目を考える。','4が不適切である。海水のイオン濃度は高く導電率を増すため、孔内・地層水へ海水が入れば通常は抵抗率が低下する。孔内流体の導電率は電極検層の測定にも影響する。',[
 ('粘性土は砂質土より一般に低比抵抗',C,'粘土表面伝導と含水が低抵抗へ寄与する。同じ流体・飽和等の比較が必要である。'),('不飽和部分は一般に高比抵抗',C,'水を通る連続導電経路が減り通常は抵抗率が上がる。鉱物・流体条件も影響する。'),('割れ目と風化が進んだ岩盤は低比抵抗',C,'含水割れ目や粘土化がある場合の傾向である。乾燥空隙や珪化を同じ低下としない。'),('海水混入で比抵抗が著しく高くなる',F,'イオンを含む海水は通常導電性が高く、淡水状態より抵抗率を下げる方向である。'),('電気検層は裸孔が基本',T,'通常の電極法では地層への電流経路を確保しケーシングによる影響を避ける。')],
 '低比抵抗を岩石名だけに対応させず、水・塩分・粘土を分ける。',['epa_resistivity','epa_borehole_resistivity'],ambiguity='粘土と砂、割れ目と健岩の比較は含水・塩分・鉱物条件に依存する。風化の全称則とはしない。')
add('H25-REG-APPLIED-35','MT・CSAMT・TDEM・Slingram・VLFの深度条件を比較する。','exploration_nearfield',['theory:exploration:nearfield','theory:exploration:fdtd'],'CSAMTの平面波近似には送受信距離が表皮深度より十分長い条件が必要である。','2が不適切である。δ=√(2ρ/(ωµ))は低周波ほど増す。固定送受信距離で周波数を下げ続けると遠方条件が破れ、近接場となるため距離によらず深く測れるとは言えない。3も装置規模・時間・ノイズから独立ではなく、その表現の疑義を保持する。',[
 ('MTは自然電磁場を使い低周波で深部を探る',C,'人工源を要せず低周波に深部感度があるが、信号強度と電気構造が推定を制限する。'),('CSAMTは距離によらず低周波化で深度増大',F,'有限送信源の近接場と平面波条件を無視する。固定距離では低周波ほどδが大きくなる。'),('TDEMは遮断後応答を測り距離によらず深度増大',C,'遮断後の時間応答を使いcentral loopでも深部に感度を持つ。ただし寸法・送信強度・測定時間・ノイズを無視した深度保証はできない。'),('Slingramは小型送受信コイルで浅部を迅速測定',T,'周波数領域の二次磁場の振幅・位相を使い、浅部導電性分布を機動的に調べる。'),('VLFは20kHz付近、方向に注意して浅部探査',T,'遠方送信局の電磁波と導電性構造の応答を使い、送信局に対する構造方位が感度へ影響する。')],
 '深さを周波数だけから決めず、有限源と電磁拡散の条件を確認する。',['usgs_csamt2012','epa_tdem_archive','epa_fdem','usgs_mt_metadata'],ambiguity='3の距離によらずという全称にも疑義がある。CSAMT遠方条件の明確な欠落を2の根拠とするが、TDEMの無条件深度増大を承認しない。VLF局と周波数は方式の典型である。')
add('H26-REG-APPLIED-22','Archie・電磁結合・CSAMT近接場・VLF・TEMを比較する。','exploration_nearfield',['theory:exploration:nearfield','theory:exploration:archie','theory:exploration:fdtd'],'遠方条件の指標は送受信距離/δであり、同一周波数では高比抵抗ほどδが増す。','3が不適切である。間隔が小さいほど近接場になり、同じ周波数・間隔では高比抵抗ほどδが大きく平面波条件が破れやすい。原典の低比抵抗を高比抵抗へ書き換えず、誤記述として保存する。',[
 ('Archieは孔隙水だけの電流を仮定する',C,'絶縁性骨格・表面伝導が無視できる孔隙ネットワークを想定する。低抵抗流体はその条件を満たしやすいが、有効孔隙率が大きければ十分とは限らない。'),('電磁カップリングがIP誤差になる',T,'送受信ケーブル間の誘導応答は分極による位相・減衰応答と重なり誤差へ寄与する。'),('CSAMT近接場は低比抵抗で生じやすい',F,'δは√ρに比例するため同一条件では高比抵抗の方が有限距離による近接場になりやすい。'),('VLFは3〜30kHz、VLF-EMとVLF-MT',T,'磁場変化を測る方式と電場磁場比を用いる方式を区別する周波数帯・分類である。'),('TEMは時間応答、一次磁場なしで測りstatic shiftが生じにくい',C,'送信遮断後の二次応答を観測し、MT電場の局所歪みとは異なる。turn-off過程・送信器残留応答などは別途扱い、生じにくいを完全ゼロへ強めない。')],
 '近接場は高/低抵抗を記憶せずδと送受信距離から判断する。',['usgs_csamt2012','epa_ip','epa_tdem_archive','epa_borehole_resistivity'],ambiguity='Archieの骨格・表面伝導条件、TEM一次場遮断の過渡とstatic shiftの比較を留保。生じにくいという原典限定を保持。')
add('H26-REG-APPLIED-23','電気・電磁法の比抵抗単位と測定配置を比較する。','exploration_dc_arrays',['theory:exploration:dcarrays','theory:exploration:fdtd'],'抵抗率ρ=RA/LなのでΩmである。電極電流と誘導電流を区別する。','4が不適切である。R=ρL/Aからρ=RA/Lとなり、Ω×m²/m=Ωmである。原典のΩ・m³は誤った単位である。',[
 ('直流又は低周波交替直流の電場から比抵抗分布を推定',T,'極性切替を含む低周波電流と電位差の測定を地盤モデルへ逆解析する。'),('電磁検層はコイル誘導、低比抵抗層に適する',C,'導電率が高い地層は誘導二次場を生みやすい。ただし誘導数・装置校正・孔状態にも依存し全範囲で精度増大とはしない。'),('人工又は自然磁場変動から比抵抗分布を効率的に測る',C,'電磁誘導応答は電気物性へ関係する。効率と面積は方式・機器に依存する。'),('比抵抗の単位はΩ・m³',F,'抵抗率は電流密度と電場の比例係数でΩmである。体積の単位を掛けると次元が違う。'),('領域を囲む電極から二次元・三次元比抵抗tomography',T,'多方向・多数電流配置の電位データを逆解析して比抵抗分布を推定する。覆い方により分解できる構造が変わる。')],
 '物性単位を試料幾何から導出し、測定名と物性を一対一に混同しない。',['epa_resistivity','epa_fdem','epa_borehole_resistivity'],ambiguity='低比抵抗層の誘導検層精度と迅速広域性は装置条件による。Ω・m³の原典上付き3を画像照合。')
add('H28-REG-APPLIED-19','電気・電磁現象と地震反射のNMO補正を区別する。','exploration_fd_td',['theory:exploration:nearfield','theory:exploration:ipsp','theory:exploration:reflectiongeometry'],'NMOは反射走時のoffset依存を補正する地震探査処理である。','1のNMO補正である。表皮・近接場・誘導分極・Schumann共振は電気・電磁応答に直接関係する。SchumannはMT電磁記録でも観測される。',[
 ('NMO補正',F,'normal moveoutは震源受振器の距離による反射走時差を補正する。電磁現象の名称ではない。'),('表皮効果',T,'導電媒質内の周期電磁場の減衰と深度感度へ関係する。'),('ニアフィールド効果',T,'有限送信源からの近距離場が平面波近似と異なることをいう。'),('IP効果',T,'電流による地下界面の分極で減衰・位相が変わる。'),('シューマン共振',T,'地球と電離層の電磁共振であり、自然MTの電場磁場記録にも現れる。')],
 '同じ探査で扱う補正でも信号の物理原理を識別する。',['schumann_mt2009','epa_ip','usgs_csamt2012'])
add('H28-REG-APPLIED-22','SP鉱体異常の符号と電気・弾性波探査を比較する。','exploration_ip_sp',['theory:exploration:ipsp','theory:exploration:dcarrays','theory:exploration:borehole'],'SPは基準点に対する電位差であり、典型的な硫化鉱体上の負異常を考える。','1が不適切である。典型的な鉱化電池の鉱体上部では基準点に対し負の電位異常を利用する。全鉱体・全自然電位源の符号を固定する規則ではない。',[
 ('鉱体があると地表電位が周囲より高い',F,'典型的な硫化鉱体探査は負の電位異常を利用し、周囲より高いという説明は逆である。酸化還元や流動の機構を特定する。'),('比抵抗垂直探査は電極間隔を広げ深さ分布を推定',T,'配置間隔を変えて深度感度を変え、水平多層等のモデルを推定する。'),('AMTは自然磁場と地電流で深部比抵抗を推定',C,'電場磁場の周波数応答で表層レーダより深い領域へ感度を持つ。実深度は周波数・抵抗率・信号品質による。'),('弾性波tomographyは周囲の起振受振で伝播特性を画像化',T,'多数経路走時などの逆解析で速度分布を求め、覆いの不足は分解能を制限する。'),down],
 '自然電位の符号を単一の地下物体の存在へ直結させない。',['epa_sp','epa_resistivity','usgs_mt_metadata','geebec_ps'],ambiguity='SPの負異常は典型的鉱化機構と基準点による。AMTの深部は相対表現であり一定深度を保証しない。')
add('H28-REG-APPLIED-23','Wenner式・ArchieとMT式の透磁率・誘電率を照合する。','exploration_nearfield',['theory:exploration:dcarrays','theory:exploration:archie','theory:exploration:nearfield'],'見掛比抵抗ρa=2πaV/Iとρa=|Ex/Hy|²/(ωµ)を使い、µは透磁率とする。','3が不適切である。式のµは真空の透磁率µ0であって誘電率ε0ではない。式の形が正しくても原典の変数定義が誤る。Wenner式とMT式の次元を独立に照合する。',[
 ('Wennerのρa=2πaV/I',T,'等間隔aの四電極を均質半空間の点電極として配置した幾何係数2πaである。'),('粘土の含水岩はArchie予測より低比抵抗',C,'粘土表面の追加導電がある場合、孔隙水のみのモデルより伝導が増える。全試料の固定差ではない。'),('MT式のµを真空の誘電率と定義する',F,'E/HからΩを持つインピーダンスを作りωµで割る。µはH/mの透磁率でありF/mの誘電率ではない。'),('TEMはループ又は接地両端電流源で深部探査',T,'磁気ループ方式だけでなく接地電流源の時間領域応答を測る構成もある。'),('VLFは3〜30kHzの既存局で送信条件を制御できない',C,'既存通信送信局を利用する受信探査では局の位置・周波数・運用を調査者が任意には設定できない。専用人工源の別方式を含めない。')],
 '式の記号の名前・単位と励起方式を照合し、形だけで正しいと判定しない。',['epa_resistivity','usgs_csamt2012','epa_borehole_resistivity','epa_tdem_archive'],ambiguity='原典は真空の誘電率をµと定義していることを画像確認。粘土の表面伝導と既存VLF局の条件を保持。')
add('H29-REG-APPLIED-32','Archieの孔隙水伝導条件と地下水・SP解釈を比較する。','exploration_archie',['theory:exploration:archie','theory:exploration:nearfield','theory:exploration:ipsp'],'孔隙水だけで電流が流れ、骨格と表面伝導を無視できる場合にArchieを使う。','4の高比抵抗孔隙水なら精度よく適用という保証が不適切である。孔隙水導電が小さいと相対的に表面伝導等が重要となり、仮定が破れやすい。清浄な絶縁骨格なら淡水でも成立し得るため、高比抵抗では絶対に不可とはしない。',[
 ('囲む電極の比抵抗tomographyで二次元・三次元分布',T,'多数配置電位差を逆解析し、覆いとモデル制約の範囲で分布を求める。'),('CSAMT近接場は小間隔・高比抵抗で生じやすい',T,'同一周波数でδ∝√ρとなるので、距離/δが小さくなる方向である。'),('平野礫帯水層は高抵抗、山地裂帯変質帯は低抵抗',C,'粘土層との比較や含水割れ目・変質粘土の対比として典型的である。塩分、空隙率、乾燥、母岩で変わる。'),('孔隙水比抵抗が高い場合にArchieを精度よく適用',F,'孔隙水以外の導電を無視できることが必要で、高抵抗水だけで精度は保証できない。表面伝導の相対的重要性が増す。'),('鉱体頂部は負異常、地熱対流は正異常',C,'典型鉱化機構と上昇流の特定条件の傾向である。熱電・化学・流動電位と基準点に依存し、全地熱地点の正符号を保証しない。')],
 '実験式の対象と地質解釈の典型を、全材料に通じる十分条件へ拡張しない。',['epa_borehole_resistivity','epa_resistivity','epa_sp','usgs_csamt2012'],ambiguity='高比抵抗水でも絶縁清浄骨格でArchieは成立し得る。礫層・割れ目・地熱SPの符号の全称は留保する。')
add('H29-REG-APPLIED-33','ばね式重力計・MT・GPR・海上音波の観測を比較する。','exploration_multimethod',['theory:exploration:observables','theory:exploration:gpr'],'ばね伸びの比較による重力差と、絶対加速度の時間長さ測定を分ける。','3が不適切である。ばねの伸びを使う多くの重力探査用装置は相対重力計である。絶対計は自由落下等の運動を長さと時間で測る。',[
 ('磁気探査で鉄の概略位置は測れるが細形状種類は判別できない',C,'磁化と形状・深度の非一意性があるため磁気だけで製品種を一意に識別しない。追加観測で形状推定ができないという絶対禁止ではない。'),('MTは自然磁場と地電流から深部比抵抗を探査',T,'電磁応答のインピーダンスと周波数から比抵抗モデルを求める。'),('ばね伸びの装置は絶対重力計',F,'標準点や基準との重力差を測る相対方式であり絶対方式と取り違える。'),('GPRは透過反射屈折を使い中心周波数10MHz程度以上',C,'通常のGPRの高周波帯の説明である。10MHzは厳密な全装置・全媒質の境界ではない。'),('海上ストリーマ受振器はハイドロフォン',T,'水中の音圧変動を受信する素子を曳航ケーブルへ多数配置する。')],
 'センサが測る量と、逆解析で推定する地下構造を分ける。',['gsi_gravity_definitions','usgs_mt_metadata','epa_gpr','usgs_marine_seismic'],ambiguity='磁気単独の非一意性を形状推定の絶対不可能性にしない。GPRの10MHzは典型的分類目安である。')
add('R01-REG-APPLIED-32','探査の時間差・環境振動と表面波のS波速度を比較する。','exploration_multimethod',['theory:exploration:surfacewaves','theory:exploration:multimethod'],'Rayleigh波の分散は主にVs分布へ関係し、時間差調査は同じ測定条件を比較する。','5が不適切である。表面波探査は分散曲線から主にS波速度構造を推定する。Rayleigh波にP成分もあるが、主推定対象をP波速度とする説明は違う。',[
 ('重力補正で密度構造による異常のみ抽出',C,'潮汐・標高・地形等の寄与を補正し地下密度異常を解釈する。補正誤差や地域背景が完全に消えるという保証ではない。'),('GPRは数m浅部の埋設物空洞遺跡に多用',T,'典型的な浅部の利用であり、媒質・装置によってより深い例もある。'),('time lapseは繰返し探査差から地下変化を推定',T,'同じ条件の反復観測で変化を見る。装置ドリフトや位置・気象差も区別する。'),('環境振動は感覚補正の振動レベルとJIS計器を使う',C,'人の周波数感度を補正した加速度レベルで評価する。出題時と現在の規格版、計器性能の全文は追加照合対象である。'),('表面波分散から主にP波速度構造を推定',F,'通常の表面波法の主推定物性はS波速度Vsである。P波速度は感度を持つ他パラメータとして扱う。')],
 '観測波の粒子運動と、その逆解析が主に拘束する物性を区別する。',['epa_surfacewaves','epa_gpr','rion_vibration2016','gsi_gravity_definitions'],ambiguity='JISの規格本文と出題時/現行版差は未照合。重力ののみは処理目的と読み、残差誤差がないとはしない。')
add('R01-RET-APPLIED-27','岩盤強度の直接試験と間接指標、圧密降伏を比較する。','engineering_strength_indices',['theory:engineering:strengthindices'],'岩石試験片の破壊強度と、割れ目を含む岩盤の状態及び土の圧密履歴を区別する。','3の圧密降伏応力である。通常は土の一次元圧縮履歴と降伏を表す量であり、他の項目は岩片強度・割れ目状態・弾性応答など岩盤評価へ直接又は間接に使う。ただし弱い泥岩等の圧縮降伏もあり、関連性を完全ゼロとはしない。',[
 ('ハンマー打診音',C,'硬さ・風化・割れ目等の現地判別に用いるが、定量強度の直接測定ではなく観察者と条件に依存する。'),('一軸圧縮強度',T,'試験片を側方無拘束で圧縮破壊させた最大応力であり、岩片材料の強度を直接評価する。岩盤の弱面は別である。'),('圧密降伏応力',F,'通常の土の圧密・応力履歴の指標であり、岩盤強度特性の比較では相対的に関係が薄い。弱岩の圧縮降伏との関連は否定しない。'),('RQD',C,'健全コアの所定長さ割合により割れ目による岩盤状態を表す。長さ品質指標そのものが一軸強度ではない。'),('弾性波速度',C,'弾性率、密度、割れ目、含水と関係し岩盤評価に使う。破壊強度との一意換算ではない。')],
 '岩片の材料試験と岩盤の割れ目・水・応力条件、代理指標を分ける。',['jseg_engineering_faq','geebec_ps'],ambiguity='岩盤評価の相対比較である。RQD・打診・波速から強度を一意に決めず、弱岩の圧縮降伏の例外を保持。',discipline='geo_engineering')
profile=('profileにより構造、wide angleで電磁波速度を推定',T,'走査波形を位置へ並べるprofileと、送受信距離を変えて走時から速度を求める構成を使い分ける。')
cross=('直線埋設物へできる限り直角の測線',T,'横切る測線で位置の変化と点状反射の走時を捉えやすくする。未知方位では複数方位を測る。')
band=('中心周波数10MHz程度以上をGPRの目安とする',C,'通常のGPRの周波数帯を示す分類目安である。電磁探査との厳密な物理境界ではない。')
no_strength=('電気境界を測るため力学特性との相関はほとんどない',C,'強度や硬さを直接測らないことは正しい。ただし含水・空隙・劣化など共通要因を通じた間接相関まで全面否定はできない。')
physical=('誘電率・導電率の異なる境界からの反射を測る',T,'電磁インピーダンスと減衰の違いを波形に捉える。地質名や機械強度を直接測る方式ではない。')
scan=('アンテナ移動の波形を順に並べ記録断面を作る',T,'横軸は測線位置、縦軸は通常往復走時であり、速度モデルから深度へ変換する。')
uses=('埋設物・空洞・地層・鉄筋・遺跡・水等を調査',C,'各対象が電磁特性の差を持ち、十分な到達深度と分解能を得られる場合の用途である。すべての現場で適用可能とはしない。')
badfreq=('中心周波数と分解能は逆比例、探査深度は比例',F,'分解できる最小距離は通常高周波ほど小さく、能力としての分解能は良くなる。深度も高周波ほど大きいという説明は通常の交換条件に反する。')
for q,stem,sol,rows,amb in [
 ('H24-REG-APPLIED-21','GPRの深度・周波数・分解能と調査配置を比較する。','3が不適切である。深部まで測るための低周波化、波の減衰・拡がりやノイズにより一般に深部の分解・検出が難しくなる。深度が増しても分解能が低下しないという一般保証はできない。',[('地表型と孔内型のレーダがある',T,'地表からの反射と孔内アンテナによる反射・透過などの構成がある。'),('周波数は探査深度と分解能へ関係',T,'波長・帯域と吸収が分解と到達深度を制限する。'),('一般に深度が増しても分解能は低下しない',F,'深部の低周波化や減衰・ビーム拡がりが分解と検出を難しくする。非低下の一般保証は不適切である。'),cross,('高分解能なので路面下空洞に利用',T,'浅部の空洞境界の電気特性差と十分な波長・信号品質を使う。')],'固定波形の理想鉛直分解能は深度そのものだけで単調低下するわけではない。実地の交換条件と検出限界を区別。'),
 ('R02-REG-APPLIED-33','GPRのMHz帯と測線・速度・強度の推定限界を照合する。','3の10kHzが不適切である。通常の地中レーダはMHz帯以上の高周波パルスを使い、10kHzを分類境界とする説明は三桁違う。2の比例は定量則ではなく分解能力と深度の傾向として限定する。',[profile,('周波数と分解能は比例、深度は逆比例',C,'周波数が高いほど分解能力が良く、深度を制限する通常の傾向である。最小識別距離は波長に比例し、実深度が厳密に1/fとなる保証はない。'),('10kHz程度以上をGPR、以下を電磁探査とする',F,'通常の目安は10MHz程度であり、kHzの桁を取り違える。物理的境界としての厳密性もない。'),cross,no_strength],'2の分解能は能力と最小距離で比例方向が変わる。深度の厳密反比例と5の間接相関全面否定は留保。'),
 ('R03-REG-APPLIED-35','GPRの比誘電率の基準と誘電率の単位を照合する。','4が不適切である。D=εEからεの単位は(C/m²)/(V/m)=F/mで、F・mではない。比誘電率は真空ε0に対する比ε/ε0である。空気は通常近似として真空に近いが厳密な定義ではない。',[physical,scan,band,('誘電率単位F・m、比誘電率は空気に対する比',F,'誘電率はF/mであり、比誘電率の基準は真空である。空気の基準は通常の近似に過ぎない。'),uses],'原典のF・mは画像照合済み。比誘電率の空気と真空、10MHz分類目安及び各用途の媒質条件を区別。'),
 ('R05-REG-APPLIED-33','GPRの周波数と分解能力・到達深度の向きを判断する。','3が不適切である。高周波では通常波長が短く分解能力が高まる一方、実地では探査深度が制限される。原典の分解能逆比例・深度比例はこの通常の向きを逆にしている。最小識別距離と能力の語を混同しない。',[no_strength,cross,badfreq,profile,band],'分解能の表現は最小距離と識別能力を区別する。実深度のf依存を厳密な比例則とせず、力学特性との共通要因による間接相関を留保。'),
 ('R06-REG-APPLIED-35','GPRの電気境界と周波数・断面・用途を比較する。','2が不適切である。高周波は通常分解能力を良くする一方、深度を大きくする保証はない。帯域と媒質導電性・ノイズを含む到達条件から判断する。',[physical,badfreq,uses,scan,band],'分解能の最小距離/能力と探査深度の交換条件を区別し、10MHzを全方式の厳密境界にしない。')]:
 add(q,stem,'exploration_gpr_resolution',['theory:exploration:gpr','theory:exploration:gprresolution'],'低損失非磁性媒質でv≈c/√εr、波長λ=v/f、パルス帯域Bに対する距離分解はおよそv/(2B)である。導電率等が到達深度を制限する。',sol,rows,'反射走時を深度と混同せず、帯域・速度・損失と探査目的を対応させる。',['epa_gpr'],ambiguity=amb)
add('R02-REG-APPLIED-34','周波数領域の位相と時間領域の過渡応答を区別する。','exploration_fd_td',['theory:exploration:fdtd','theory:exploration:multimethod'],'正弦波定常応答は振幅と位相、遮断後応答は時間に対する減衰を測る。','4が不適切である。Slingram等の周波数領域電磁法は連続正弦送信に対する受信振幅と位相差を測る。過渡応答は時間領域の測定である。',[
 ('微小重力差の相対測定や鉛直重力勾配を利用',C,'0.01mGal級以下の精度を持つ計器の利用と勾配観測がある。全装置と測定現場に共通の精度保証ではない。'),('領域を囲む信号源センサで物性を逆解析',T,'tomographyの観測覆いと感度に沿って物性分布を推定する。'),('検層で比抵抗密度速度孔隙率等を深度に記録',C,'物性を連続記録し、孔隙率のように複数物性と校正から推定する量もある。すべてが直接測定ではない。'),('周波数領域で連続波の振幅と過渡応答を測る',F,'定常の振幅と位相を測る方式と、遮断後の時間領域過渡を混同する。'),('AEは微小破壊で主破壊に先行することが多い',C,'微小破壊に伴う弾性波放出が前兆の研究対象になる。主破壊前だけの定義又は常に発生する保証ではない。')],
 'f領域の位相とt領域の減衰、直接物性と校正推定量を分ける。',['epa_fdem','epa_tdem_archive','sato_lei2009_ae','gsi_gravity_definitions'],ambiguity='精度0.01mGalは機器/現場の条件値、検層孔隙率は間接推定、AEの先行は全称ではない。')
add('R03-REG-APPLIED-32','比抵抗の深度感度と自然電位法の逆解析限界を比較する。','exploration_ip_sp',['theory:exploration:ipsp','theory:exploration:dcarrays'],'SPは自然電位差の分布を直接測り、源の深度には機構・形状・抵抗率のモデルが必要である。','公式の4を保持する。SP観測から地下水や鉱体の深さを簡単に直接求めるという読みなら不適切である。一方、半幅や源モデル、他観測との逆解析により深度推定の例はあり、深度を探査・解析するという広い原典表現自体が全面的に不可能とは言えない。疑義を査読対象にする。',[
 ('IPは印加電流の分極応答、硫化鉱物探査に用いる',T,'金属・電解質界面等の分極で電位の時間減衰や周波数位相が生じ、鉱床や環境調査に使われる。'),('垂直探査は水平多層の鉛直比抵抗を推定',T,'電極間隔を変えて深度感度を変化させ、WennerやSchlumberger等の配置で層モデルを推定する。'),('水平探査は特定深さの水平比抵抗変化を調べる',C,'固定間隔等で感度深度をおおむねそろえ横方向を調べる。ただし有限体積の重み付き応答で一点の厳密深度だけを測らない。'),('SPから地下水や鉱床の深さを探査解析し簡単安全に測る',C,'自然電位分布の簡単な受動測定はできるが、深度は非一意で源モデルや他データが必要である。深度解析が全く不可能とも言えず、この候補の否定範囲は未確定である。'),('多電極の直流電位から比抵抗tomography',T,'多数の注入・受信対の応答を順モデルへ合わせて比抵抗分布を推定する。')],
 '公式の選択と、科学的に否定できる命題の範囲を分けて残す。',['epa_sp','epa_ip','epa_resistivity'],ambiguity='4にはモデル依存の深度推定が可能という反例がある。公式4を保持するが「SPで深度解析はできない」という誤解を教えない。3の特定深さも有限感度体積の近似。')
add('R05-REG-APPLIED-35','表面波のVsと磁気・tomography・地温の感度を比較する。','exploration_multimethod',['theory:exploration:surfacewaves','theory:exploration:multimethod'],'観測の空間覆い、密度差、温度差と、Rayleigh分散の主Vs感度を考える。','2が不適切である。Rayleigh波分散から通常主にS波速度分布を推定する。20mは典型装置・設定の深度であり、全表面波法の深度限界ではない。',[
 ('地上磁気探査で水平分解能数mの浅部調査',C,'細かい測点と近い対象で詳細調査が可能である。実分解能は深度、磁化、観測配置、ノイズによる。'),('Rayleigh波から20m程度までP波速度分布',F,'主推定対象はS波速度Vsである。深度の数値も測定波長・配置に依存する。'),('地下tomographyの構造像は測定幾何に依存',T,'全方向から測れず、覆いのない方向・領域の分解は制限される。'),('密度差が大きい対象は重力で検出しやすい',C,'同じ形状・深度・ノイズ条件なら密度差が重力異常を増す。深い小対象との無条件比較ではない。'),('1m深地温で地熱温泉や地すべり地下水を調査',C,'流動水と平常地温の温度差を利用する。測温1mと地下水源の深度は別で、適期や地表環境の補正が必要である。')],
 '典型的数値を固定限界とせず、主観測量・感度・配置をそろえて比較する。',['epa_surfacewaves','gsi_gravity_definitions','naro_thermal2008','landslide_thermal2007'],ambiguity='磁気数m・表面波20mは設定依存、熱探査は温度差と季節・地況による。1mを水脈の上限深度としない。')
add('H25-REG-APPLIED-33','重力・速度検層・屈折法と起伏地の反射法の制約を比較する。','exploration_multimethod',['theory:exploration:refraction','theory:exploration:reflectiongeometry'],'地形起伏は走時・観測配置へ影響し、浅層反射法では静補正や起振受振条件を整える。','5が不適切である。急峻で凹凸の多い地形を浅層反射法の一般的な適用対象とする説明は、走時補正・起振結合・配置の難しさを落としている。ただし適切な補正と計測により適用可能な例を否定しない。',[
 ('重力分布から地下密度構造を推定',T,'重力異常に対して密度と形状のモデルを作り逆解析する。'),('単孔で波速の深さ分布を求める速度検層',T,'地表又は孔内起振と孔内受振の走時を用いる。'),('屈折波から地下速度構造を解析',C,'通常は速い下層の境界を進み戻る臨界屈折波の初動等を使う。任意の低速度層まで検出できるわけではない。'),('下方増速で速度比大きいほど分割と厚さ精度が良い',C,'層走時勾配の差が明瞭になり識別しやすい傾向である。隠れ層、薄層、配置、ノイズによる精度制限もある。'),('浅層反射法は急峻で凹凸の多い場所へ適用される',F,'通常の適用上は地形起伏が観測と補正の障害となり、適性を積極的に示す一般記述は不適切である。実施そのものが絶対不可能とはしない。')],
 '適用の一般的有利条件と、補正して実施できる可能性を分ける。',['epa_seismic_reflection','epa_seismic_refraction','usgs_static2004','geebec_ps'],ambiguity='地形起伏があれば反射法は絶対不可とはしない。速度比だけから層厚精度を保証せず、隠れ層と観測条件を保持。')
